window.MG_LAZY_DATA["data/lazy/courses/d310-d54ca1e8d956cce2.json"]={sha256:"d54ca1e8d956cce2442de0ca50ee0d2be7acea87ec59e76f9c14bd34221830c1",value:{"id":"d310","title":"卡倫堡工業共生系統","titleEn":"Kalundborg Industrial Symbiosis","category":"process","kind":"course","summary":"以卡倫堡為背景，從資源盤點、介面計量到合作治理建立工業共生概念方案。","summaryEn":"Use Kalundborg as context for a conceptual industrial-symbiosis proposal covering resource inventories, metering interfaces and cooperation.","scope":"三階段十二步以原創虛構企業與明示假設帳進行概念規劃；官方案例支持原理與歷史，不代表提供現行合約或實際管網數據。不是工廠連接、處理配方、法律合約或完整操作 SOP。","scopeEn":"Three stages and twelve tasks use fictional firms and explicitly assumed accounts for conceptual planning. Official cases support principles and history, not current contracts or real pipeline data. This is not a plant-connection procedure, treatment recipe, legal contract or complete operating SOP.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-science-kalundborg","v6-science-kalundborg-about","v6-science-symbiosis-facilitation"],"depth":4,"diagram":{"type":"process","labels":["來源廠","資源卡","交換介面","接收用途","共同治理"],"labelsEn":["Source plant","Resource card","Exchange interface","Receiving use","Joint governance"],"original":true,"notToScale":true},"stages":[{"id":"d310-stage01","order":1,"title":"邊界與資源適配","titleEn":"Boundaries and resource fit","description":"建立組織網路、盤點欄位與比較基準。","descriptionEn":"Establish the organizational network, inventory fields and baseline.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d310-v6-01","order":1,"sequence":1,"prerequisiteIds":[],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-kalundborg-about"],"title":"劃定跨企業資源交換網路","titleEn":"Define an inter-company resource network","objective":"將供應者、使用者與資源責任畫在同一系統圖。","objectiveEn":"Put suppliers, users and resource responsibilities on one system diagram.","instruction":"畫來源廠 A、接收廠 B 與第三方設施 C；分別標水、能源、物料箭頭及跨企業負責者。","instructionEn":"Draw source plant A, receiving plant B and third-party facility C; label water, energy and material arrows and inter-company owners.","observation":"資源可以跨企業循環，但品質與交付責任仍需明確。","observationEn":"Resources can circulate across firms while quality and delivery responsibilities still need definition.","failure":"只畫循環箭頭不標所有者，會隱藏跨企業介面。","failureEn":"Drawing loops without owners hides inter-company interfaces.","check":"每條交換線均有來源、接收者、資源類型與責任欄。","checkEn":"Give each exchange a source, receiver, resource type and responsibility field.","knowledge":[{"id":"d310-v6-01-k1","title":"工程原理","titleEn":"Engineering principle","text":"工業共生將一個參與者的剩餘資源連到另一個參與者的需求。","textEn":"Industrial symbiosis links one participant’s surplus resources to another participant’s needs."},{"id":"d310-v6-01-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"A、B、C 是原創教學角色，不代表官方網路的特定現行合約。","textEn":"A, B and C are original teaching roles, not specific current contracts in the official network."}],"quiz":{"question":"哪條連接最容易進行介面審查？","questionEn":"Which connection is easiest to review?","options":["同時標示資源、兩端組織與責任","只有箭頭，沒有資源類別","把所有公司合併成無責任單一節點"],"optionsEn":["One naming the resource, both organizations and responsibility","An arrow without a resource type","All companies merged into an ownerless node"],"answer":0,"explanation":"工業共生將一個參與者的剩餘資源連到另一個參與者的需求。 A、B、C 是原創教學角色，不代表官方網路的特定現行合約。","explanationEn":"Industrial symbiosis links one participant’s surplus resources to another participant’s needs. A, B and C are original teaching roles, not specific current contracts in the official network."}},{"id":"d310-v6-02","order":2,"sequence":2,"prerequisiteIds":["d310-v6-01"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-symbiosis-facilitation"],"title":"建立資源盤點欄位","titleEn":"Build a resource inventory","objective":"讓數量、時間與品質資訊可以比較。","objectiveEn":"Make quantity, timing and quality information comparable.","instruction":"設計三張資源卡，欄位包括名稱、數量單位、時段、品質限制與資料來源。","instructionEn":"Design three resource cards with name, quantity unit, time window, quality constraints and data source.","observation":"同名資源可能因濃度、溫度或供應時段不同而不可互換。","observationEn":"Resources with the same name may not be interchangeable because of composition, temperature or timing.","failure":"只記年總量會漏掉季節性與品質差異。","failureEn":"Recording annual totals alone misses seasonality and quality differences.","check":"每張卡均能回答多少、何時、何種品質與由誰提供證據。","checkEn":"Each card must answer how much, when, at what quality and who provides evidence.","knowledge":[{"id":"d310-v6-02-k1","title":"工程原理","titleEn":"Engineering principle","text":"交換可行性需要數量、品質、時間與位置同時匹配。","textEn":"Exchange feasibility requires matching quantity, quality, timing and location."},{"id":"d310-v6-02-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"未知資料應標待查證，不以零或最高品質代填。","textEn":"Unknown information should be marked unverified, not replaced with zero or the highest quality."}],"quiz":{"question":"只有資源名稱與年總量時，還缺什麼？","questionEn":"What is missing when only a resource name and annual total are known?","options":["更多裝飾圖示","時間分布、品質與介面資料","相同數值再重複一次"],"optionsEn":["More decorative icons","Timing, quality and interface information","The same value repeated once more"],"answer":1,"explanation":"交換可行性需要數量、品質、時間與位置同時匹配。 未知資料應標待查證，不以零或最高品質代填。","explanationEn":"Exchange feasibility requires matching quantity, quality, timing and location. Unknown information should be marked unverified, not replaced with zero or the highest quality."}},{"id":"d310-v6-03","order":3,"sequence":3,"prerequisiteIds":["d310-v6-02"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-symbiosis-facilitation"],"title":"保存交換前的比較基準","titleEn":"Preserve the pre-exchange baseline","objective":"定義節省量所比較的原始情境。","objectiveEn":"Define the original scenario against which savings are compared.","instruction":"分開列出無交換與有交換兩種情境的外購資源、處理需求與共同產出邊界。","instructionEn":"List purchased resources, treatment needs and common output boundaries for scenarios without and with exchange.","observation":"只有產出與時間窗一致，節省量才有明確意義。","observationEn":"Savings are meaningful only when outputs and time windows are consistent.","failure":"把低產量年度與高產量年度直接比較，會把減產誤當效率改善。","failureEn":"Comparing low- and high-output years directly can mistake reduced production for efficiency gains.","check":"確認兩情境交付同等功能，並記錄所有假設差異。","checkEn":"Confirm equivalent delivered function and record all differing assumptions.","knowledge":[{"id":"d310-v6-03-k1","title":"工程原理","titleEn":"Engineering principle","text":"基準情境決定效益計算的比較對象。","textEn":"The baseline defines the comparison used to calculate benefits."},{"id":"d310-v6-03-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課不重算官方減碳宣稱，只建立可審查比較方法。","textEn":"This course builds a reviewable comparison method rather than recalculating official carbon claims."}],"quiz":{"question":"哪兩個情境最適合比較交換效益？","questionEn":"Which scenarios best support comparison of exchange benefits?","options":["產量和季節都不同且不作校正","只比較公司名稱長短","相同功能與時間窗，僅交換安排不同"],"optionsEn":["Different outputs and seasons without adjustment","Compare company-name lengths only","Same function and time window, with exchange arrangements differing"],"answer":2,"explanation":"基準情境決定效益計算的比較對象。 本課不重算官方減碳宣稱，只建立可審查比較方法。","explanationEn":"The baseline defines the comparison used to calculate benefits. This course builds a reviewable comparison method rather than recalculating official carbon claims."}},{"id":"d310-v6-04","order":4,"sequence":4,"prerequisiteIds":["d310-v6-03"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg-about","v6-science-symbiosis-facilitation"],"title":"篩選來源與需求的匹配","titleEn":"Screen source–demand matches","objective":"識別數量吻合但品質不合的假匹配。","objectiveEn":"Identify false matches where quantity fits but quality does not.","instruction":"設計來源卡「可供 10、品質未驗證」與需求卡「需要 8、品質需確認」，以紅黃綠分類但不批准連接。","instructionEn":"Create source card “10 available, quality unverified” and demand card “8 needed, quality confirmation required”; classify readiness without approving a connection.","observation":"數量看似足夠，品質未知仍是未完成的匹配。","observationEn":"Quantity may appear sufficient while unknown quality leaves the match incomplete.","failure":"只因 10 大於 8 就判定可直接使用，會漏掉適用性。","failureEn":"Approving use because 10 exceeds 8 overlooks fitness for purpose.","check":"為數量、品質、時間、地點各列一個獨立狀態。","checkEn":"Give quantity, quality, timing and location separate status fields.","knowledge":[{"id":"d310-v6-04-k1","title":"工程原理","titleEn":"Engineering principle","text":"工業交換需要滿足接收用途的條件，不能只看供應量。","textEn":"Industrial exchange must satisfy receiving-use conditions, not only supply volume."},{"id":"d310-v6-04-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"分類是概念篩選，實際連接需專業評估、協議與適用許可。","textEn":"Classification is conceptual screening; real connections need professional assessment, agreements and applicable permissions."}],"quiz":{"question":"上述來源與需求應如何標示？","questionEn":"How should the source and demand be marked?","options":["數量初步足夠，品質仍待確認","所有條件自動通過","接收端需求完全不重要"],"optionsEn":["Quantity provisionally sufficient; quality still unverified","All conditions automatically passed","Receiving requirements do not matter"],"answer":0,"explanation":"工業交換需要滿足接收用途的條件，不能只看供應量。 分類是概念篩選，實際連接需專業評估、協議與適用許可。","explanationEn":"Industrial exchange must satisfy receiving-use conditions, not only supply volume. Classification is conceptual screening; real connections need professional assessment, agreements and applicable permissions."}}]},{"id":"d310-stage02","order":2,"title":"守恆與交換介面","titleEn":"Conservation and exchange interfaces","description":"審查物料、熱、水與計量邊界。","descriptionEn":"Review material, heat, water and metering boundaries.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d310-v6-05","order":1,"sequence":5,"prerequisiteIds":["d310-v6-04"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-symbiosis-facilitation"],"title":"閉合單一物料交換帳","titleEn":"Close a single-material exchange account","objective":"把接收量、剩餘量與損失分開。","objectiveEn":"Separate received quantity, remainder and losses.","instruction":"用同一時段的假設帳：來源 10、接收 7、已知其他去向 1，求尚待交代的餘量。","instructionEn":"Use an assumed same-period account: source 10, received 7 and known other destination 1; calculate the unaccounted remainder.","observation":"餘量為 2；不能因畫了交換箭頭就假設全部被利用。","observationEn":"The remainder is 2; an exchange arrow does not imply complete utilization.","failure":"把來源 10 與接收 7 都算為節省 17，會重複計數。","failureEn":"Counting source 10 and receipt 7 as savings of 17 double-counts the transfer.","check":"來源等於接收加其他去向加餘量，並檢查單位一致。","checkEn":"Verify source equals received plus other destinations plus remainder, using consistent units.","knowledge":[{"id":"d310-v6-05-k1","title":"工程原理","titleEn":"Engineering principle","text":"物料在網路中的內部移轉不會創造額外物質。","textEn":"Internal transfers within a network do not create additional material."},{"id":"d310-v6-05-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本帳為自設例題，未交代餘量不是官方網路的實際排放或損失。","textEn":"This invented exercise does not identify real emissions or losses in the official network."}],"quiz":{"question":"例題尚待交代的餘量是多少？","questionEn":"What remainder is still unaccounted for?","options":["17","2","0，因為資源已經循環"],"optionsEn":["17","2","0, because the resource circulates"],"answer":1,"explanation":"物料在網路中的內部移轉不會創造額外物質。 本帳為自設例題，未交代餘量不是官方網路的實際排放或損失。","explanationEn":"Internal transfers within a network do not create additional material. This invented exercise does not identify real emissions or losses in the official network."}},{"id":"d310-v6-06","order":2,"sequence":6,"prerequisiteIds":["d310-v6-05"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-symbiosis-facilitation"],"title":"區分熱量與溫度適用性","titleEn":"Distinguish heat quantity from temperature suitability","objective":"理解餘熱總量不能單獨決定用途。","objectiveEn":"Understand why total surplus heat alone cannot determine its use.","instruction":"畫來源熱流與兩個需求端，一個需求溫度較低、一個較高；用概念箭頭標出需進一步評估的提升介面。","instructionEn":"Draw a heat source and two demands at lower and higher temperature requirements; mark any upgrading interface needing evaluation.","observation":"熱量相同的來源，因溫度不同而可能適合不同需求。","observationEn":"Sources with equal heat quantities can suit different demands because their temperatures differ.","failure":"只看能量總數相等就宣告可直接替代，會忽略熱品位。","failureEn":"Declaring direct substitution from equal energy totals ignores heat quality.","check":"同時列熱量單位與溫度條件，未知者保留空缺說明。","checkEn":"Record both heat quantity units and temperature conditions, explaining unknowns.","knowledge":[{"id":"d310-v6-06-k1","title":"工程原理","titleEn":"Engineering principle","text":"熱的可利用性取決於溫差、需求與轉換介面。","textEn":"Heat usefulness depends on temperature difference, demand and conversion interfaces."},{"id":"d310-v6-06-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課不提供蒸汽管線、熱泵或受壓設備的設計操作參數。","textEn":"The lesson provides no design or operating settings for steam lines, heat pumps or pressure equipment."}],"quiz":{"question":"評估餘熱交換時，除了熱量還需什麼？","questionEn":"What is needed besides heat quantity when assessing heat exchange?","options":["只需來源廠商標誌","把熱量全部改成沒有單位的分數","來源與需求的溫度及介面條件"],"optionsEn":["Only the source company’s logo","Convert all heat quantities to unitless scores","Source and demand temperatures and interface conditions"],"answer":2,"explanation":"熱的可利用性取決於溫差、需求與轉換介面。 本課不提供蒸汽管線、熱泵或受壓設備的設計操作參數。","explanationEn":"Heat usefulness depends on temperature difference, demand and conversion interfaces. The lesson provides no design or operating settings for steam lines, heat pumps or pressure equipment."}},{"id":"d310-v6-07","order":3,"sequence":7,"prerequisiteIds":["d310-v6-06"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-symbiosis-facilitation"],"title":"確認水的用途適配","titleEn":"Check water fitness for purpose","objective":"避免把回用水標籤當作所有用途都合格。","objectiveEn":"Avoid treating a reused-water label as approval for every use.","instruction":"以三張虛構需求卡列冷卻、清洗與更高品質製程用水；分別列待驗證的品質項。","instructionEn":"Create fictional cooling, washing and higher-quality process-water demand cards, listing quality evidence needed for each.","observation":"同一水源可以適合一種用途而不適合另一種用途。","observationEn":"One water source can fit one use while failing another.","failure":"把所有水需求合成單一容量欄會掩蓋交叉污染風險與品質限制。","failureEn":"Merging all water demands into one capacity field hides contamination concerns and quality constraints.","check":"每個用途有獨立品質欄、來源與未驗證標記，不設定飲用安全結論。","checkEn":"Give every use a separate quality field, source and verification status without declaring drinking-water safety.","knowledge":[{"id":"d310-v6-07-k1","title":"工程原理","titleEn":"Engineering principle","text":"資源循環需要符合接收用途，回用本身不保證品質。","textEn":"Circular use must meet receiving requirements; reuse alone does not guarantee quality."},{"id":"d310-v6-07-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"這是用途分類練習，不是水處理配方或供水驗收規範。","textEn":"This is a use-classification exercise, not a treatment recipe or water-supply acceptance specification."}],"quiz":{"question":"「可回用」標籤能否證明所有用途都適合？","questionEn":"Does a “reusable” label establish suitability for every use?","options":["不能，需逐用途核對品質條件","可以，只要數量足夠","可以，水的用途不影響要求"],"optionsEn":["No; quality conditions must be checked for each use","Yes, if the quantity is sufficient","Yes; water use does not affect requirements"],"answer":0,"explanation":"資源循環需要符合接收用途，回用本身不保證品質。 這是用途分類練習，不是水處理配方或供水驗收規範。","explanationEn":"Circular use must meet receiving requirements; reuse alone does not guarantee quality. This is a use-classification exercise, not a treatment recipe or water-supply acceptance specification."}},{"id":"d310-v6-08","order":4,"sequence":8,"prerequisiteIds":["d310-v6-07"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg-about","v6-science-symbiosis-facilitation"],"title":"界定計量與所有權交接點","titleEn":"Define metering and ownership-transfer points","objective":"使雙方對交換數量採一致邊界。","objectiveEn":"Give both parties a consistent boundary for exchanged quantities.","instruction":"在 A 到 B 的概念線上畫兩個計量點與一個交接點，標時間窗與誰保管讀值。","instructionEn":"Draw two meter points and one handover point on an A-to-B concept line, marking time windows and record owners.","observation":"兩端讀值差異可能涉及時間、庫存、損失或儀表偏差。","observationEn":"Differences between end readings can involve timing, storage, losses or meter bias.","failure":"未對齊時間就直接歸咎某一方，會把記帳差異誤判為違約。","failureEn":"Blaming one party before aligning time windows can mistake accounting differences for non-compliance.","check":"比較前先統一單位與時間，再列差值的替代解釋。","checkEn":"Align units and time before comparison, then list alternative explanations for differences.","knowledge":[{"id":"d310-v6-08-k1","title":"工程原理","titleEn":"Engineering principle","text":"計量點與責任交接點可能不同，必須明確記錄。","textEn":"Metering and responsibility-transfer points can differ and must be documented."},{"id":"d310-v6-08-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"概念線不揭示真實管線位置，也不授權接管或調整儀表。","textEn":"The concept line reveals no real pipeline route and authorizes no connection or meter adjustment."}],"quiz":{"question":"兩端讀值不同時第一步應是什麼？","questionEn":"What comes first when endpoint readings differ?","options":["立刻宣告其中一方違約","核對時間窗、單位與計量邊界","任選一個數字刪掉另一個"],"optionsEn":["Immediately declare one party in breach","Check time windows, units and metering boundaries","Keep either number and delete the other"],"answer":1,"explanation":"計量點與責任交接點可能不同，必須明確記錄。 概念線不揭示真實管線位置，也不授權接管或調整儀表。","explanationEn":"Metering and responsibility-transfer points can differ and must be documented. The concept line reveals no real pipeline route and authorizes no connection or meter adjustment."}}]},{"id":"d310-stage03","order":3,"title":"合作、韌性與交接","titleEn":"Cooperation, resilience and handover","description":"處理時間承諾、中斷依賴與效益歸屬。","descriptionEn":"Address time commitments, interruption dependencies and benefit attribution.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d310-v6-09","order":1,"sequence":9,"prerequisiteIds":["d310-v6-08"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg-about","v6-science-symbiosis-facilitation"],"title":"比較承諾供應與實際可用性","titleEn":"Compare committed supply with actual availability","objective":"辨識長期合作中時間與品質承諾的作用。","objectiveEn":"Identify the role of timing and quality commitments in cooperation.","instruction":"建立虛構交換協議欄：資源品質、交付時窗、資料責任、異常通知與變更審查。","instructionEn":"Create fictional agreement fields for quality, delivery windows, data ownership, incident notification and change review.","observation":"年度總量承諾不能取代停機期間的供應安排。","observationEn":"An annual quantity commitment cannot replace arrangements for outages.","failure":"只寫平均供應量卻不說中斷，會使接收端高估連續性。","failureEn":"Listing only average supply without interruptions overstates continuity for the receiver.","check":"為供應中斷情境列通知對象與需共同決策的資料，不寫現場處置命令。","checkEn":"For an interruption scenario, list recipients and information for joint decisions, without field-response instructions.","knowledge":[{"id":"d310-v6-09-k1","title":"工程原理","titleEn":"Engineering principle","text":"跨企業合作需要共享資訊與清楚的責任安排。","textEn":"Inter-company cooperation needs shared information and clear responsibilities."},{"id":"d310-v6-09-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"協議欄是教學框架，不是可直接簽署的法律合約。","textEn":"These agreement fields are a teaching framework, not a ready-to-sign legal contract."}],"quiz":{"question":"哪項最能補足平均供應量的不足？","questionEn":"What best complements an average supply quantity?","options":["更大的公司名稱字體","刪除所有異常情境","供應時窗、中斷通知與品質責任"],"optionsEn":["A larger company-name font","Removing all exception scenarios","Supply windows, interruption notification and quality responsibilities"],"answer":2,"explanation":"跨企業合作需要共享資訊與清楚的責任安排。 協議欄是教學框架，不是可直接簽署的法律合約。","explanationEn":"Inter-company cooperation needs shared information and clear responsibilities. These agreement fields are a teaching framework, not a ready-to-sign legal contract."}},{"id":"d310-v6-10","order":2,"sequence":10,"prerequisiteIds":["d310-v6-09"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg-about","v6-science-symbiosis-facilitation"],"title":"推演一條交換中斷的影響","titleEn":"Trace the effects of an interrupted exchange","objective":"辨識依賴關係與備援需求。","objectiveEn":"Identify dependencies and fallback needs.","instruction":"在 A→B→C 的教學網路移除 A→B，標示直接與間接受影響節點；列替代供應待驗證欄。","instructionEn":"Remove A→B from the teaching network A→B→C, mark direct and indirect effects, and list alternative-supply verification needs.","observation":"下游依賴可能讓一次中斷影響多個參與者。","observationEn":"Downstream dependencies can spread one interruption across several participants.","failure":"假定備援資源必然相容，可能把品質不合的物料送入下游。","failureEn":"Assuming fallback compatibility can pass unsuitable material downstream.","check":"每個替代方案重新核對數量、品質、時間與責任，不自動繞過檢查。","checkEn":"Recheck quantity, quality, timing and responsibility for each alternative without bypassing checks.","knowledge":[{"id":"d310-v6-10-k1","title":"工程原理","titleEn":"Engineering principle","text":"網路韌性取決於依賴結構與已驗證的替代路徑。","textEn":"Network resilience depends on dependencies and verified alternatives."},{"id":"d310-v6-10-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"推演只在紙上進行，不要求改動任何現場管網或供應。","textEn":"This is a paper exercise and requires no changes to real networks or supplies."}],"quiz":{"question":"A→B 中斷後，哪個判斷最合理？","questionEn":"After A→B fails, which judgment is most reasonable?","options":["B 直接受影響，C 可能因依賴而受影響","只有 A 的圖示需要改色","任意資源都可立即取代原供應"],"optionsEn":["B is directly affected; C may be affected through dependence","Only A’s icon needs recolouring","Any resource can immediately replace the original supply"],"answer":0,"explanation":"網路韌性取決於依賴結構與已驗證的替代路徑。 推演只在紙上進行，不要求改動任何現場管網或供應。","explanationEn":"Network resilience depends on dependencies and verified alternatives. This is a paper exercise and requires no changes to real networks or supplies."}},{"id":"d310-v6-11","order":3,"sequence":11,"prerequisiteIds":["d310-v6-10"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-symbiosis-facilitation"],"title":"避免節省量重複歸屬","titleEn":"Avoid double attribution of savings","objective":"區分公司個別效益與網路總效益。","objectiveEn":"Distinguish individual benefits from network-wide benefits.","instruction":"假設一筆交換替代 7 單位外購資源；分列供應者、接收者與網路總帳，標明共同受益。","instructionEn":"Assume one exchange replaces 7 units of purchased resource; separate supplier, receiver and network accounts and mark shared benefits.","observation":"雙方均可受益，但同一筆物理替代量在總帳只計一次。","observationEn":"Both parties can benefit, but the same physical substitution is counted once in the total.","failure":"把兩家都報的 7 相加為 14，會高估網路節省。","failureEn":"Adding the 7 reported by each firm into 14 overstates network savings.","check":"每筆效益都有唯一交換編號、基準與歸屬規則。","checkEn":"Give each benefit a unique exchange ID, baseline and attribution rule.","knowledge":[{"id":"d310-v6-11-k1","title":"工程原理","titleEn":"Engineering principle","text":"聚合效益需排除重複計數並維持一致邊界。","textEn":"Aggregated benefits require removing double-counting and keeping consistent boundaries."},{"id":"d310-v6-11-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"物料節省不是自動等同碳減量，後者還需適用係數與邊界。","textEn":"Material savings do not automatically equal carbon reductions, which need suitable factors and boundaries."}],"quiz":{"question":"同一筆 7 單位替代在網路總帳應記多少？","questionEn":"How much should the network count for one 7-unit substitution?","options":["14 單位，因為有兩家公司","7 單位，並揭露歸屬方式","沒有單位，只寫效益很大"],"optionsEn":["14 units, because two companies are involved","7 units, with attribution disclosed","No units; simply state large benefits"],"answer":1,"explanation":"聚合效益需排除重複計數並維持一致邊界。 物料節省不是自動等同碳減量，後者還需適用係數與邊界。","explanationEn":"Aggregated benefits require removing double-counting and keeping consistent boundaries. Material savings do not automatically equal carbon reductions, which need suitable factors and boundaries."}},{"id":"d310-v6-12","order":4,"sequence":12,"prerequisiteIds":["d310-v6-11"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-kalundborg","v6-science-kalundborg-about","v6-science-symbiosis-facilitation"],"title":"完成共生網路的分期交接","titleEn":"Complete a staged symbiosis-network handover","objective":"把資源適配、治理與證據整合為可審查方案。","objectiveEn":"Integrate resource fit, governance and evidence into a reviewable proposal.","instruction":"提交網路圖、資源卡、基準與交換帳、異常推演及資料缺口清單；為每項指派驗證責任。","instructionEn":"Submit the network map, resource cards, baseline and exchange accounts, interruption exercise and data gaps, assigning verification responsibility.","observation":"方案成熟度由已確認的介面與合作證據決定，不能只看連線數量。","observationEn":"Proposal maturity depends on verified interfaces and collaboration evidence, not the number of links alone.","failure":"把未驗證交換全部標成完成，會讓後續決策失去依據。","failureEn":"Marking every unverified exchange as complete removes the basis for later decisions.","check":"按已知、假設、待確認三類審查，讓另一位學徒追算一次總帳。","checkEn":"Review known, assumed and unverified items, and have another learner trace one total account.","knowledge":[{"id":"d310-v6-12-k1","title":"工程原理","titleEn":"Engineering principle","text":"工業共生是持續協調的社會與工程系統。","textEn":"Industrial symbiosis is an engineering and social system requiring continuing coordination."},{"id":"d310-v6-12-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"十二步是概念規劃，不代表已取得真實資源、商業協議或運作許可。","textEn":"These twelve tasks are conceptual planning, not access to real resources, commercial agreements or operating permissions."}],"quiz":{"question":"哪份方案最適合交給下一位工程師？","questionEn":"Which proposal is best for the next engineer?","options":["只有漂亮循環圖而沒有資料","把所有缺漏標成不重要","附證據、責任與未解介面的版本"],"optionsEn":["An attractive loop diagram without data","One labelling every gap unimportant","A version with evidence, responsibilities and unresolved interfaces"],"answer":2,"explanation":"工業共生是持續協調的社會與工程系統。 十二步是概念規劃，不代表已取得真實資源、商業協議或運作許可。","explanationEn":"Industrial symbiosis is an engineering and social system requiring continuing coordination. These twelve tasks are conceptual planning, not access to real resources, commercial agreements or operating permissions."}}]}],"status":"guided","languageCoverage":["zh-TW","en"],"curriculumVersion":6,"stepCount":12,"estimatedMinutes":240}};
